const canvas=$('#static-screen'),ctx=canvas.getContext('2d');let w=600,h=360,mode='idle',field,phase=0,last=performance.now(),held=false,handsFree=false,slow=matchMedia('(prefers-reduced-motion: reduce)').matches,sound=false,audio,beatTimer,beat=0,started=0,finished=0,motionMs=0,totalMotion=0,caught=0,attempts=3,haunt=1,rotation=0,lastScratch=-Infinity,dragAngle=null,cursor={x:.5,y:.5,visible:false},events=[],toastTimer,hitMarker=null;
function seed(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]}
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0)}new ResizeObserver(resize).observe(canvas);resize();
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4500)}
function modal(title,content){$('#modal-content').innerHTML=`<span class="note-label">GHOST//FUNK · DEPARTMENT OF SOUL SCIENCE</span><h2>${title}</h2>${content}<button class="note-button" id="note-ok">THAT’S THE SPIRIT. ↗</button>`;$('#modal').showModal();$('#note-ok').onclick=()=>$('#modal').close()}
function tone(f,d=.12,v=.025,type='triangle',delay=0){if(!sound||!audio)return;const t=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+d)}
function sting(){[261.63,311.13,392,523.25].forEach((f,i)=>tone(f,.22,.04,'triangle',i*.065))}
function setAudio(){clearInterval(beatTimer);if(!sound)return;const play=()=>{const notes=[65.41,0,65.41,77.78,0,87.31,98,0,65.41,0,116.54,98,0,87.31,77.78,0];const i=beat++%16;if(notes[i])tone(notes[i],.18,.028,'sawtooth');if(i%4===0)tone(48,.15,.11,'sine');if(i%4===2){tone(190,.08,.035);tone(2200,.03,.007,'square')}tone(6500,.025,.003,'square');if(i%8===0)[261.63,311.13,392].forEach(f=>tone(f,.12,.008))};play();beatTimer=setInterval(play,150)}
$('#sound').onclick=async()=>{try{audio??=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();sound=!sound;$('#sound').setAttribute('aria-pressed',String(sound));$('#sound span').textContent=sound?'SOUND ON':'SOUND OFF';setAudio()}catch{toast('The DJ has been exorcised by your browser. Visual play still works.')}};
function update(){const labels=['01','02'];labels.forEach((label,i)=>{$(`#case-${i===0?'one':'two'}`).textContent=label+' · '+(caught>i?'CAPTURED':'UNCAUGHT');$(`#case-${i===0?'one':'two'}`).classList.toggle('done',caught>i)});$('#caught').innerHTML=`${caught} <i>/ 2</i>`;$('#attempts').innerHTML=`${attempts} <i>NO PRESSURE. SOME PRESSURE.</i>`;$('#serial').textContent='HAUNT #'+String(haunt).padStart(3,'0');$('#autoplay').setAttribute('aria-pressed',String(handsFree));$('#slow').setAttribute('aria-pressed',String(slow))}
function freshField(){const previous=field?.ghost;field=makeField(seed(),previous);motionMs=0;lastScratch=-Infinity;hitMarker=null;cursor.visible=false;phase=0;$('#motion-time').textContent='00.0s'}
function begin(){mode='active';caught=0;attempts=3;events=[];started=performance.now();finished=0;totalMotion=0;freshField();$('#screen-overlay').classList.add('hidden');$('#screen-result').classList.add('hidden');$('#feedback').textContent='HOLD THE RECORD OR SWITCH ON HANDS-FREE SPIN. LOOK FOR THE LARGE GHOST-SHAPED PATCH MOVING TOGETHER.';$('#signal-state').textContent='LISTENING';$('#field-status').textContent='GHOST 01 / FIND THE COHERENT SHAPE';update()}
function reset(){mode='idle';held=false;handsFree=false;lastScratch=-Infinity;field=null;motionMs=0;caught=0;attempts=3;started=finished=0;events=[];haunt++;hitMarker=null;$('#screen-overlay').classList.remove('hidden');$('#screen-result').classList.add('hidden');$('#feedback').textContent='FRESH VINYL. FRESH HAUNTING. SAME QUESTIONABLE AFTERLIFE.';$('#signal-state').textContent='STANDBY';$('#field-status').textContent='WAITING FOR A HUMAN MOMENT';$('#timer').textContent='00:00';$('#motion-time').textContent='00.0s';update()}
$('#start').onclick=begin;$('#reset').onclick=reset;
function result(title,text,button,fn,winning=false){const el=$('#screen-result');el.classList.remove('hidden');el.innerHTML=`<div class="big-boo">${winning?'✳':'☻'}</div><h2>${title}</h2><p>${text}</p><button id="continue">${button} ↗</button>${winning?'<button class="result-reset" id="play-again">ONE MORE HAUNT. I HAVE ISSUES. ↺</button>':''}`;$('#continue').onclick=fn;if(winning)$('#play-again').onclick=reset}
function capture(x,y){if(mode!=='active')return;const judged=judgeCapture({x,y,ghost:field.ghost,motionMs});if(judged.reason==='play the record first'){$('#feedback').textContent='THE GHOST ONLY GIVES IT AWAY IN MOTION. PLAY THE RECORD FOR A MOMENT FIRST.';return}events.push({haunt:caught+1,accepted:judged.accepted,reason:judged.reason,motionMs:Math.round(motionMs)});hitMarker={x,y,accepted:judged.accepted,at:performance.now()};if(judged.accepted){caught++;held=false;sting();update();if(caught===2){mode='won';finished=performance.now();$('#signal-state').textContent='SOULS FOUND';$('#field-status').textContent='VERIFICATION EXPERIMENT COMPLETE';$('#feedback').textContent='TWO FRESH SOULS. ZERO PERSONAL DATA. AN UNREASONABLE AMOUNT OF FUNK.';result('YOU’VE GOT<br>SOUL.',`Two ghosts captured in ${((finished-started)/1000).toFixed(1)}s.<br>This demo passed. Your taste in music remains under review.`,'GET MY SOUL LICENSE',downloadPass,true)}else{mode='between';$('#signal-state').textContent='GOT ONE';$('#feedback').textContent='FIRST SOUL SECURED. THE NEXT ONE HAS MOVED. OLD COORDINATES WON’T HELP.';result('BOO-YAH.<br>ONE TO GO.','You found the shape in the motion.<br>Fresh ghost. Fresh position. Same haunted record.','SUMMON THE NEXT SOUL',()=>{mode='active';freshField();$('#screen-result').classList.add('hidden');$('#signal-state').textContent='LISTENING';$('#field-status').textContent='GHOST 02 / NEW LOCATION';$('#feedback').textContent='SECOND HAUNT. PLAY AGAIN. LOOK FOR THE SHAPE THAT MOVES TOGETHER.'})}}else{attempts--;tone(100,.2,.035,'sawtooth');if(attempts===0){mode='lost';held=false;$('#signal-state').textContent='GHOSTED';$('#feedback').textContent='THREE MISSES. THE GHOSTS CHANGED THEIR ADDRESS.';result('YOU GOT<br>GHOSTED.','Not a moral failing. Just a very slippery soul.<br>Start fresh, play the record, and watch the motion.','FRESH HAUNTING',begin)}else{freshField();$('#feedback').textContent='MISSED. THE GHOST RELOCATED. WATCH THE MOVING SHAPE BEFORE YOU TAP.';$('#field-status').textContent='NEW SOUL POSITION / '+attempts+' ATTEMPTS LEFT'}update()}}
canvas.addEventListener('pointerdown',e=>{if(mode!=='active')return;const r=canvas.getBoundingClientRect();capture((e.clientX-r.left)/w,(e.clientY-r.top)/h)});
canvas.addEventListener('keydown',e=>{if(mode!=='active')return;const step=e.shiftKey?.012:.035;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();cursor.visible=true;if(e.key==='ArrowLeft')cursor.x=Math.max(.02,cursor.x-step);if(e.key==='ArrowRight')cursor.x=Math.min(.98,cursor.x+step);if(e.key==='ArrowUp')cursor.y=Math.max(.02,cursor.y-step);if(e.key==='ArrowDown')cursor.y=Math.min(.98,cursor.y+step)}else if(e.key==='Enter'){e.preventDefault();capture(cursor.x,cursor.y)}else if(e.code==='Space'){e.preventDefault();held=true}});canvas.addEventListener('keyup',e=>{if(e.code==='Space'){e.preventDefault();held=false}});canvas.addEventListener('blur',()=>{held=false});
const record=$('#record');function angle(e){const r=record.getBoundingClientRect();return Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2)}
record.onpointerdown=e=>{e.preventDefault();if(mode==='idle'){toast('Drop the needle in the booth first. Then hold or scratch this record.');return}if(mode!=='active')return;held=true;dragAngle=angle(e);record.setPointerCapture(e.pointerId)};
record.onpointermove=e=>{if(!held||dragAngle===null)return;const a=angle(e);let delta=a-dragAngle;if(delta>Math.PI)delta-=Math.PI*2;if(delta<-Math.PI)delta+=Math.PI*2;phase+=delta*1.8;rotation+=delta*180/Math.PI;dragAngle=a;lastScratch=performance.now();tone(160+Math.abs(delta)*450,.035,.008,'sawtooth')};
record.onpointerup=record.onpointercancel=()=>{held=false;dragAngle=null};record.onlostpointercapture=()=>{held=false;dragAngle=null};record.onkeydown=e=>{if(e.code==='Space'){e.preventDefault();if(mode==='active')held=true}};record.onkeyup=e=>{if(e.code==='Space'){e.preventDefault();held=false}};record.onblur=()=>{held=false};record.onclick=e=>{if(e.detail===0&&mode==='active'){handsFree=!handsFree;update()}};
$('#autoplay').onclick=()=>{handsFree=!handsFree;update();if(mode==='idle')toast('Hands-free is ready. Drop the needle to start the hunt.')};$('#slow').onclick=()=>{slow=!slow;update();toast(slow?'SLOW GROOVE ON. Same soul, gentler motion.':'REGULAR GROOVE. The ghost is back on the dance floor.')};
